(4554054, 655199, 90784, '<td valign="top">Beautiful light!</td>', 'Beautiful light!', '2008-03-11 01:12:40.000000', NULL, 1),
(4554056, 655899, 26001, '<td valign="top">such a simple idea (firing flash twice in a long exposure), so elegantly used to execute one of the simplest yet very clever interpretation of the challenge. colors, composition, exposure, model''s expression everything is just right. one of my favourites in the challenge.</td>', 'such a simple idea (firing flash twice in a long exposure), so elegantly used to execute one of the simplest yet very clever interpretation of the challenge. colors, composition, exposure, model''s expression everything is just right. one of my favourites in the challenge.', '2008-03-11 01:12:52.000000', NULL, 1),
(4554065, 655756, 69668, '<td valign="top">An excellent image.  My favorite in the entire challenge. Beautiful soft light just enhances this image and really makes it stand out for me.  I hope to see a ribbon with this image.  Such a great job.</td>', 'An excellent image.  My favorite in the entire challenge. Beautiful soft light just enhances this image and really makes it stand out for me.  I hope to see a ribbon with this image.  Such a great job.', '2008-03-11 01:17:13.000000', NULL, 1),
(4554067, 654206, 69668, '<td valign="top">A very good image for the cahllenge.  Sharp and nice use of blocking the light from being to pwerful on his face. I like it.</td>', 'A very good image for the cahllenge.  Sharp and nice use of blocking the light from being to pwerful on his face. I like it.', '2008-03-11 01:17:58.000000', NULL, 1),
(4554068, 655756, 26001, '<td valign="top">excellent catch and masterfully photographed. i love the smoothness of the water in out-of-focus areas. one of the best uses of NeatImage I have seen to date.</td>', 'excellent catch and masterfully photographed. i love the smoothness of the water in out-of-focus areas. one of the best uses of NeatImage I have seen to date.', '2008-03-11 01:17:59.000000', NULL, 1),
