INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4567918, 655582, 76185, '<td valign="top">Clean and simple. A little too smooth for my taste but overall effect comes together well.</td>', 'Clean and simple. A little too smooth for my taste but overall effect comes together well.', '2008-03-16 19:37:08.000000', NULL, 1),
(4567921, 656204, 76185, '<td valign="top">Nice composition, wonder if having the subject a little lower in frame would help? Placing feels a little squashed.<br/> <br/>Like the texture of the wood and the shadow on the face adds interest.</td>', 'Nice composition, wonder if having the subject a little lower in frame would help? Placing feels a little squashed. Like the texture of the wood and the shadow on the face adds interest.', '2008-03-16 19:39:20.000000', NULL, 1),
(4567924, 656073, 76185, '<td valign="top">Another bit of strange sculpture? Edges look jaggy, presumably from the mask. Struggling to see how this addresses the challenge.</td>', 'Another bit of strange sculpture? Edges look jaggy, presumably from the mask. Struggling to see how this addresses the challenge.', '2008-03-16 19:40:47.000000', NULL, 1),
(4567928, 654120, 76185, '<td valign="top">Very seductive. I like the lighting here and the translucent look of the cloth. Appealing and different take on the challenge.</td>', 'Very seductive. I like the lighting here and the translucent look of the cloth. Appealing and different take on the challenge.', '2008-03-16 19:43:06.000000', NULL, 1),
(4567929, 653886, 76185, '<td valign="top">Cute :) A little flat/harsh with the lighting perhaps?</td>', 'Cute :) A little flat/harsh with the lighting perhaps?', '2008-03-16 19:43:35.000000', NULL, 1),
(4567930, 656329, 76185, '<td valign="top">Thought there might be a lot of this type of shot. Works well and the softness is appealing.</td>', 'Thought there might be a lot of this type of shot. Works well and the softness is appealing.', '2008-03-16 19:44:18.000000', NULL, 1),
(4567932, 655770, 76185, '<td valign="top">Very alien looking. Great macro, sharp and interesting subject.</td>', 'Very alien looking. Great macro, sharp and interesting subject.', '2008-03-16 19:44:55.000000', NULL, 1),
(4567935, 654206, 76185, '<td valign="top">Curious expression :) not sure about the shadow but the worn wood gives a suitable framing.</td>', 'Curious expression :) not sure about the shadow but the worn wood gives a suitable framing.', '2008-03-16 19:46:57.000000', NULL, 1),
(4567938, 655835, 76185, '<td valign="top">I like this take on the challenge. I think perhaps it looks oversharpened with detracts for me.</td>', 'I like this take on the challenge. I think perhaps it looks oversharpened with detracts for me.', '2008-03-16 19:47:53.000000', NULL, 1),
